import json
from pathlib import Path

BENCHMARKS = ['mmlu', 'gsm8k', 'arc_challenge']
SIGNALS = ['s1_embedding', 's2_minkpp', 's4_selfcritique']

for bench in BENCHMARKS:
    by_item = {}
    for sig in SIGNALS:
        fpath = Path(f'signal_{sig}_{bench}.json')
        if not fpath.exists():
            print(f'MISSING: {fpath}')
            continue
        data = json.loads(fpath.read_text())
        for r in data:
            item_id = r['item_id']
            if item_id not in by_item:
                by_item[item_id] = {'item_id': item_id, 'benchmark': bench}
            by_item[item_id][r['signal']] = r['score']

    merged = sorted(by_item.values(), key=lambda x: x['item_id'])
    out = Path(f'signals_merged_{bench}.json')
    out.write_text(json.dumps(merged, indent=2))
    print(f'{bench}: {len(merged)} items merged -> {out}')
"

